import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErratumIcon } from "../components/ErratumIcon";

const erratumIconElem = document.getElementById("gacha-clue-erratum-icon");
if (erratumIconElem) {
  const { clueId, hasErratum } = (
    erratumIconElem as HTMLElement & {
      dataset: { clueId?: string; hasErratum?: string };
    }
  ).dataset;

  if (clueId) {
    hydrateRoot(
      erratumIconElem,
      <ErratumIcon
        resource={{ type: "clue", slug: clueId }}
        hasErratum={hasErratum === "true"}
        iconClassName="h-5 w-5 text-rose-500"
      />,
    );
  } else {
    console.error(
      "Could not hydrate gacha clue erratum icon because clueId was missing",
    );
  }
}
